"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[15807],{15807:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/about-death.png\\"\\n          title=\\"About Death\\"\\n          author=\\"Sini\\"\\n          publisher=\\"Youngcom\\"\\n          publishedDate=\\"2013-03-04\\"\\n          isbn=\\"9788996885177\\"\\n          rating=5\\n          tags=\\"story\\"\\n        />\\n</center>\\n\\n## Review\\nA ```God``` who is an observer rather than omnipotent appears, and does not directly intervene in human fate.  \\nMiracles such as bringing the dead back to life or preventing a destined death are not his role.  \\n<br>\\nHe is not a judge, but a mirror that makes the deceased look back on their lives themselves.  \\nAnd he listens to the final stories of the deceased.  \\nIn this process, the deceased realize for themselves the truths, regrets, and precious values they had ignored in their lives.  \\n<br>\\nEach episode consists of chilling stories about death, and gives new meaning and emotion every time it is read and pondered.  "}')}}]);